/*
 * This is a manifest file that'll be compiled into application.css, which will include all the files
 * listed below.
 *
 * Any CSS (and SCSS, if configured) file within this directory, lib/assets/stylesheets, or plugin's
 * vendor/assets/stylesheets directory can be referenced here using a relative path.
 *
 *= require_tree .
 *= require_self
 */

:root {
  --todo-black: #1E1E1E;
  --todo-white: #FFFFFF;
  --todo-error: #CC3D3D;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--todo-white);
  color: var(--todo-black);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input {
  font: inherit;
}

.page-shell {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 64px 24px;
}

.todo-panel {
  width: min(100%, 900px);
  overflow: hidden;
  background: var(--todo-white);
  border: 4px solid var(--todo-black);
  border-radius: 18px;
}

.todo-panel__header {
  padding: 18px 24px;
  background: var(--todo-black);
}

.todo-panel__header--with-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.todo-panel__header h1 {
  margin: 0;
  font-style: normal;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  text-align: center;
  color: var(--todo-white);
  vertical-align: middle;
}

.todo-panel__body {
  display: flex;
  flex-direction: column;
  gap: 28px;
  padding: 48px;
}

.inline-create-form {
  position: relative;
  width: 100%;
}

.text-input {
  width: 100%;
  min-height: 86px;
  padding: 18px 112px 18px 36px;
  border: 4px solid var(--todo-black);
  border-radius: 36px;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
  outline: none;
}

.text-input::placeholder {
  color: rgba(30, 30, 30, 0.8);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
}

.input-action {
  position: absolute;
  top: 50%;
  right: 0;
  width: 86px;
  height: 86px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  transform: translateY(-50%);
  cursor: pointer;
}

.error-overlay {
  position: fixed;
  z-index: 1000;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 24px;
}

.error-box {
  position: relative;
  width: min(100%, 900px);
  max-height: 100%;
  overflow-y: auto;
  padding: 64px 72px 48px;
  border: 4px solid var(--todo-error);
  border-radius: 36px;
  background: var(--todo-white);
  color: var(--todo-error);
  box-shadow: 0 12px 40px rgba(30, 30, 30, 0.24);
}

.error-box__close {
  position: absolute;
  top: 16px;
  right: 20px;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--todo-error);
  font-size: 44px;
  line-height: 1;
  cursor: pointer;
}

.error-box p {
  margin: 0;
  color: var(--todo-error);
  font-size: 32px;
  line-height: 120%;
  text-align: center;
}

.error-box p + p {
  margin-top: 12px;
}

.items-list {
  display: block;
}

.items-list--scrollable {
  max-height: calc(6 * 64px + 5 * 24px);
  overflow-y: auto;
}

.empty-state {
  margin: 0;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: center;
  vertical-align: middle;
}

.pagination-frame__loading {
  margin: 0;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 24px;
  line-height: 100%;
  text-align: center;
}

.todo-row {
  display: flex;
  align-items: center;
  gap: 20px;
  min-height: 64px;
  margin-bottom: 24px;
}

.todo-row:last-child {
  margin-bottom: 0;
}

.todo-row__text {
  flex: 1;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  vertical-align: middle;
  overflow-wrap: anywhere;
}

.todo-row__link {
  text-decoration: none;
}

.todo-row__link:hover,
.todo-row__link:focus {
  text-decoration: underline;
}

.todo-row__text--completed {
  text-decoration: line-through;
}

.button_to {
  margin: 0;
  line-height: 0;
}

.completion-button,
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.completion-button,
.completion-button img,
.unchecked-circle {
  width: 48px;
  height: 48px;
}

.unchecked-circle {
  display: inline-block;
  border: 4px solid var(--todo-black);
  border-radius: 50%;
}

.unchecked-circle--light {
  border-color: var(--todo-white);
}

.complete-all-action {
  flex: 0 0 auto;
}

.complete-all-action__circle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--todo-white);
}

.complete-all-action__circle .button_to {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.complete-all-button,
.complete-all-button img {
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
}

.icon-button,
.icon-button img {
  width: 64px;
  height: 64px;
}

.back-link {
  color: var(--todo-black);
  font-size: 24px;
  text-align: center;
}

@media (max-width: 640px) {
  .page-shell {
    padding: 24px 12px;
  }

  .todo-panel__header h1 {
    font-size: 36px;
    line-height: 44px;
  }

  .todo-panel__body {
    padding: 28px 18px;
  }

  .error-overlay {
    padding: 24px 12px;
  }

  .error-box {
    padding: 56px 28px 32px;
  }

  .text-input,
  .text-input::placeholder,
  .todo-row__text,
  .empty-state,
  .error-box p {
    font-size: 24px;
  }
}

