  vertical-align: middle;
}

.todo-title-frame {
  flex: 1 1 auto;
  min-width: 0;
}

.todo-title__link {
  color: inherit;
  text-decoration: none;
}

.todo-title__link:hover,
.todo-title__link:focus {
  text-decoration: underline;
}

.todo-title-form {
  position: relative;
}

.todo-title-form__input {
  width: 100%;
  min-height: 72px;
  padding: 4px 204px 4px 24px;
  border: 4px solid var(--todo-white);
  border-radius: 24px;
  background: var(--todo-black);
  outline: none;
}

.todo-title-form__overlay {
  position: absolute;
  top: 50%;
  right: 10px;
  display: flex;
  gap: 8px;
  padding: 6px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.14);
  transform: translateY(-50%);
}

.todo-title-form__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 14px;
